/// The blocks of the actions the screen named `screen` offers, in the
/// order the manifest lists them. A lookup.
pub fn for_screen(screen: &str) -> Vec<&'static Block> {
    blocks()
        .iter()
        .filter(|b| b.screens.contains(&screen))
        .collect()
}

/// Whether any block is offered on `screen`. A lookup.
pub fn offered(screen: &str) -> bool {
    blocks().iter().any(|b| b.screens.contains(&screen))
}

/// The block of the action `id`. A lookup.
pub fn block(id: &str) -> Option<&'static Block> {
    blocks().iter().find(|b| b.id == id)
}

/// The blocks a Learn page carries after its sections: those whose
/// `learn` is `page`. A lookup.
pub fn for_page(page: &str) -> Vec<&'static Block> {
    blocks().iter().filter(|b| b.learn == page).collect()
}

